<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Forms;

use Override;
use Psr\Http\Message\ResponseInterface;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepName;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\Oidc\MagicLink\Application\Usecase\RequestMagicLink\RequestMagicLinkUsecase;
use Civi\Lughauth\Features\Oidc\Theme\Application\DecorateHtml;
use Civi\Lughauth\Shared\Infrastructure\Translation\MessageProvider;

class MagicLinkLoginForm implements StepForm
{
    public function __construct(
        private readonly MessageProvider $messages,
        private readonly RequestMagicLinkUsecase $requestMagicLink,
        private readonly DecorateHtml $decorator,
        private readonly HtmlSecurer $securer,
    ) {
    }

    #[Override]
    public function render(StepInput $input, ResponseInterface $response, ?AuthenticationResult $error): StepResult
    {
        $locale = '';
        $tenant = $input->context->tenant;
        $translator = $this->messages->messages('forms', $locale, __DIR__ . '/../../Translations');

        if ($error?->error === AuthenticationResult::ERR_MAGIC_LINK_SENT) {
            $response->getBody()->write($this->decorator->getFullPage(
                $input->request,
                $translator->get('magic-link.sent.title'),
                $this->buildConfirmHtml($translator),
                $locale,
                'index',
                $tenant,
            ));
            return StepResult::render($response, $input->challenges);
        }

        $js = $this->securer->configureScripts([
            $this->securer->addSign('sign'),
            $this->securer->focusOn('email'),
        ]);

        $response->getBody()->write($this->decorator->getFullPage(
            $input->request,
            $translator->get('magic-link.ask.title'),
            $js . $this->buildAskHtml($translator),
            $locale,
            'index',
            $tenant,
        ));
        return StepResult::render($response, $input->challenges);
    }

    #[Override]
    public function authenticate(StepInput $input): StepResult
    {
        $email = (string) ($input->body['email'] ?? '');

        $this->requestMagicLink->request(
            email: $email,
            clientId: $input->authRequest->client->id,
            redirectUri: $input->authRequest->redirect,
            tenantName: $input->context->tenant,
            scope: $input->authRequest->scope,
            state: $input->context->state !== '' ? $input->context->state : null,
            nonce: $input->context->nonce,
        );

        throw new LoginException(AuthenticationResult::waitMagicLink());
    }

    private function buildAskHtml(object $translator): string
    {
        $step = StepName::MAGIC_LINK->value;
        $title = $translator->get('magic-link.ask.title');
        $help = $translator->get('magic-link.ask.help');
        $emailLabel = $translator->get('magic-link.ask.email');
        $send = $translator->get('magic-link.ask.send');
        $backText = $translator->get(
            'magic-link.ask.back-text',
            ['<input class="inline" type="submit" value="' . $translator->get('magic-link.ask.back-label') . '" />'],
        );

        return <<<HTML
            <h1>{$title}</h1>
            <p>{$help}</p>
            <form method="POST">
                <input type="hidden" name="csid" id="sign" />
                <input type="hidden" name="step" value="{$step}" />
                <label>{$emailLabel}
                    <input type="email" name="email" id="email" value="" autocomplete="email" />
                </label>
                <input class="primary-button" type="submit" value="{$send}" />
            </form>
            <form method="POST">
                <input type="hidden" name="step" value="" />
                {$backText}
            </form>
            HTML;
    }

    private function buildConfirmHtml(object $translator): string
    {
        $title = $translator->get('magic-link.sent.title');
        $help = $translator->get('magic-link.sent.help');
        $backText = $translator->get(
            'magic-link.sent.back-text',
            ['<input class="inline" type="submit" value="' . $translator->get('magic-link.sent.back-label') . '" />'],
        );

        return <<<HTML
            <h1>{$title}</h1>
            <p>{$help}</p>
            <form method="POST">
                <input type="hidden" name="step" value="" />
                {$backText}
            </form>
            HTML;
    }
}
